/* ---------------------------------------------------------------------
   Signature motif: an eight-pointed star, hand-plotted on a 40x40 grid.
   Islamic geometric star-and-line work is the visual backbone of the
   whole page — it stands in for the generic gradient blob / icon-tile
   patterns, and it's specific to what ALC actually teaches.
--------------------------------------------------------------------- */
const STAR_POINTS =
  "20,3 22.49,13.99 32.02,7.98 26.01,17.51 37,20 26.01,22.49 32.02,32.02 22.49,26.01 20,37 17.51,26.01 7.98,32.02 13.99,22.49 3,20 13.99,17.51 7.98,7.98 17.51,13.99";

export function StarMark({ className = "", strokeWidth = 1.6 }: { className?: string; strokeWidth?: number }) {
  return (
    <svg viewBox="0 0 40 40" className={className} fill="none">
      <polygon
        points={STAR_POINTS}
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinejoin="round"
      />
    </svg>
  );
}

function StarStrip({ className = "", id, tone = "#8B0000", opacity = 0.5 }: { className?: string; id: string; tone?: string; opacity?: number }) {
  const patternId = `star-strip-${id}`;
  return (
    <svg className={className} preserveAspectRatio="none" style={{ color: tone, opacity }}>
      <defs>
        <pattern id={patternId} width="40" height="40" patternUnits="userSpaceOnUse">
          <polygon points={STAR_POINTS} fill="none" stroke="currentColor" strokeWidth="1" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill={`url(#${patternId})`} />
    </svg>
  );
}

